let posReceiptBlob=null,posReceiptId=null,posReceiptUrl=null,posReceiptWorking=false,posReceiptRevision=0,posReceiptGeneration=0,posUndoId=null,posUndoTimer=null,posFeeOwner=null,posFeeEditing=null;
const posLive=()=>JianjiPossessions.live(data.possessions||[]);
async function syncPosReminders(){if(!onAndroid())return;const status=await window.Capacitor.nativePromise('Reminder','status',{});reminderEnabled=!!status.enabled;await syncReminders();}
function resetPosReceipt(){++posReceiptGeneration;posReceiptWorking=false;posReceiptBlob=null;posReceiptId=null;posReceiptRevision=0;if(posReceiptUrl)URL.revokeObjectURL(posReceiptUrl);posReceiptUrl=null;}
async function compressPosPicture(file){if(file.size>30*1024*1024)throw new Error('图片超过 30 MB');const bitmap=await createImageBitmap(file),scale=Math.min(1,1400/Math.max(bitmap.width,bitmap.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(bitmap.width*scale));c.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(bitmap,0,0,c.width,c.height);bitmap.close();const blob=await new Promise(r=>c.toBlob(r,'image/jpeg',.84));if(!blob)throw new Error('图片处理失败');return blob;}
function receiptPreview(){if(posReceiptUrl)URL.revokeObjectURL(posReceiptUrl);posReceiptUrl=null;$('posReceiptPreview').replaceChildren();if(posReceiptBlob){posReceiptUrl=URL.createObjectURL(posReceiptBlob);const img=new Image();img.src=posReceiptUrl;img.alt='购买或保修凭证';$('posReceiptPreview').append(img);}$('posReceiptRemove').hidden=!posReceiptBlob;}
async function choosePosReceipt(file){if(!file)return;const gen=++posReceiptGeneration;posReceiptWorking=true;try{const blob=await compressPosPicture(file);if(gen!==posReceiptGeneration||posView!=='editor')return;posReceiptBlob=blob;posReceiptId=null;++posReceiptRevision;receiptPreview();}catch(e){toast(e.message||'凭证无法读取');}finally{if(gen===posReceiptGeneration)posReceiptWorking=false;}}
function extraPosSnapshot(){return {values:['posTarget','posWarranty','posMaintenance','posLead'].map(id=>$(id).value),care:$('posCareEnabled').checked,receipt:posReceiptRevision};}
async function fillPosExtras(p){resetPosReceipt();$('posTarget').value=p?.targetDailyCents?(p.targetDailyCents/100).toFixed(2):'';$('posWarranty').value=p?.warrantyDate||'';$('posMaintenance').value=p?.maintenanceDate||'';$('posLead').value=String(p?.reminderDays??7);$('posCareEnabled').checked=p?.careReminders===true;$('possessionsForm').querySelector('.pos-extra-options').open=false;receiptPreview();posReceiptId=p?.receiptPhotoId||null;const gen=posReceiptGeneration;if(posReceiptId){posReceiptWorking=true;try{const loaded=await photoStore('get',posReceiptId);if(gen!==posReceiptGeneration)return;posReceiptBlob=loaded;if(!posReceiptBlob){posReceiptId=null;toast('凭证图片无法读取，请重新选择');}receiptPreview();}finally{if(gen===posReceiptGeneration)posReceiptWorking=false;}}}
function getPosExtras(){return {targetDailyCents:$('posTarget').value?JianjiLife.cents($('posTarget').value):0,warrantyDate:$('posWarranty').value,maintenanceDate:$('posMaintenance').value,reminderDays:Number($('posLead').value),careReminders:$('posCareEnabled').checked};}
function posGoalMarkup(p){const g=JianjiPossessions.goal(p);if(!g)return '<p class="import-help">在“编辑物品 → 小目标与售后”设置日均成本小目标。</p>';return `<section class="pos-goal-card"><span class="pos-goal-star">${g.reached?'✦':'◷'}</span><div><b>${g.reached?'日均小目标已达成':'每天，离小目标近一点'}</b><p>目标 ${posAmount(p.targetDailyCents/100)} / 天${g.reached?'':g.ended?' · 持有已结束，成本不再自动下降':` · 预计还需 ${g.remaining} 天`}</p><div class="track"><div class="fill" style="width:${g.percent}%"></div></div><small>${g.reached?'按当前净成本计算，陪伴已让目标实现':g.ended?`距离目标天数还差 ${g.remaining} 天`:g.date?'预计 '+formatDate(g.date)+' 达标（按当前成本持续持有）':'预计日期超出可展示范围'}</small>${g.reached?'<button type="button" data-pos-achievement>生成小成就卡 ↗</button>':''}</div></section>`;}
function careMarkup(p){const lines=[['warrantyDate','保修到期'],['maintenanceDate','下次保养']].filter(([k])=>p[k]).map(([k,n])=>{const d=Math.floor((Date.parse(p[k])-Date.parse(lifeToday()))/86400000);return `<div><b>${n}</b><span>${formatDate(p[k])}</span><small>${d<0?'日期已过':d===0?'就是今天':`还有 ${d} 天`}</small></div>`;}).join('');return `<section class="pos-care-card"><h3>售后与保养</h3>${lines||'<p class="import-help">暂无保修或保养日期</p>'}<p class="import-help">${p.careReminders?'已设置本物品提醒，提前 '+(p.reminderDays??7)+' 天；已卖出、退役或删除时暂停。':'本物品提醒未开启'}</p>${p.receiptPhotoId?'<button type="button" data-pos-receipt>查看购买／保修凭证 ›</button>':''}<button type="button" data-pos-enable-reminders>${onAndroid()?'检查／开启系统提醒':'网页仅提供应用内提示'}</button><small id="posNativeReminderStatus"></small></section>`;}
function extendPosDetail(p){const cost=JianjiPossessions.costs(p),hero=$('possessionsDetail').querySelector('.poss-detail-cost');hero.querySelector('small').textContent='日均净成本';hero.querySelector('p').textContent=cost.net<0?'回收金额已超过购入与追加费用':JianjiPossessions.metrics(p).ended?'净成本固定按结束时的持有天数计算':'按当前净成本计算，持续持有会降低日均成本';const foot=$('possessionsDetail').querySelector('.poss-footnote');foot.textContent='净成本 = 购入金额 + 追加费用 − 回收金额。这里不产生真实收支；负值表示回收超过投入。';const sections=`<section class="pos-net-card"><h3>这件物品的真实成本</h3><div class="pos-net-numbers"><span>购入<b>${posAmount(p.priceCents/100)}</b></span><span>追加<b>${posAmount(cost.added/100)}</b></span><span>回收<b>${posAmount(cost.recovered/100)}</b></span></div><p>净投入 <strong>${posAmount(cost.net/100)}</strong></p><button type="button" data-pos-costs>费用与回收记录 ›</button></section>${posGoalMarkup(p)}${careMarkup(p)}<button class="quiet-button" type="button" data-pos-share>做一张物品回顾卡 ↗</button>`;foot.insertAdjacentHTML('beforebegin',sections);refreshPosCareStatus();}
async function refreshPosCareStatus(){const el=$('posNativeReminderStatus');if(!el)return;if(!onAndroid()){el.textContent='打开归物本查看即将到期的日期。';return;}try{const s=await window.Capacitor.nativePromise('Reminder','status',{});reminderEnabled=!!s.enabled;if(el!==$('posNativeReminderStatus'))return;el.textContent=!s.enabled?'系统提醒尚未开启':!s.permission?'请在系统设置允许简记发送通知':'系统提醒已开启 · 实际到达时间受省电设置影响';}catch{el.textContent='无法读取系统提醒状态';}}
async function posEnableReminders(){if(!onAndroid())return toast('网页在归物本中显示到期提示');const before=reminderEnabled;try{reminderEnabled=true;await syncReminders(true);await refreshPosCareStatus();}catch(e){reminderEnabled=before;toast(e.message||'系统提醒开启失败');}}
async function purgeExpiredPossessions(){if(!$('appLockOverlay').hidden)return;const old=JianjiPossessions.expired(data.possessions||[]);if(!old.length)return;const ids=new Set(old.map(p=>p.id));await changeLife(()=>data.possessions=data.possessions.filter(p=>!ids.has(p.id)));for(const p of old)for(const id of [p.photoId,p.receiptPhotoId])await cleanPosPhoto(id);syncPosReminders().catch(()=>{});}
async function softDeletePossession(id){const p=posLive().find(x=>x.id===id);if(!p)return;await changeLife(()=>p.deletedAt=new Date().toISOString());await syncPosReminders().catch(()=>toast('物品已移入回收站，系统提醒未更新'));posScreen('list');renderPossessions();posUndoId=id;clearTimeout(posUndoTimer);$('posUndoBar').hidden=false;posUndoTimer=setTimeout(()=>{$('posUndoBar').hidden=true;posUndoId=null;},8000);}
async function restorePossession(id){const p=data.possessions.find(p=>p.id===id&&p.deletedAt);if(!p)return;if(JianjiPossessions.expired([p]).length){await purgeExpiredPossessions();return toast('已超过 30 天保留期');}await changeLife(()=>delete p.deletedAt);await syncPosReminders().catch(()=>toast('物品已恢复，系统提醒未更新'));if($('posTrashModal').classList.contains('show'))renderPosTrash();else renderPossessions();toast('物品及照片已恢复');}
function renderPosTrash(){posReleaseList();const list=data.possessions.filter(p=>p.deletedAt).sort((a,b)=>b.deletedAt.localeCompare(a.deletedAt));$('posTrashList').innerHTML=list.map(p=>`<article class="pos-trash-row">${posThumb(p)}<div><b>${escapeHtml(p.name)}</b><small>还保留约 ${Math.max(0,Math.ceil((30*86400000-Date.now()+Date.parse(p.deletedAt))/86400000))} 天</small><div><button data-pos-restore="${p.id}" type="button">恢复</button><button data-pos-purge="${p.id}" type="button">永久删除</button></div></div></article>`).join('')||'<div class="empty">没有已删除的物品</div>';posLoadPictures($('posTrashList'));}
function openPosFees(id){posFeeOwner=id;posFeeEditing=null;$('posFeeForm').hidden=true;renderPosFees();open('posFeeModal');}
function renderPosFees(){const p=posLive().find(p=>p.id===posFeeOwner);if(!p){close('posFeeModal');return;}const c=JianjiPossessions.costs(p);$('posFeeSummary').innerHTML=`<b>${escapeHtml(p.name)}</b><p>净投入 ${posAmount(c.net/100)}</p><small>购入 ${posAmount(p.priceCents/100)} ＋ 追加 ${posAmount(c.added/100)} − 回收 ${posAmount(c.recovered/100)}</small>`;$('posFeesList').innerHTML=(p.fees||[]).slice().sort((a,b)=>b.date.localeCompare(a.date)).map(f=>`<article class="pos-fee-row"><div><b>${escapeHtml(f.name)}</b><small>${formatDate(f.date)} · ${f.kind==='expense'?'追加费用':'回收金额'}${f.entryId?' · 已关联账目':''}</small></div><strong>${posAmount(f.cents/100)}</strong><div><button data-pos-fee-edit="${f.id}" type="button">编辑</button><button data-pos-fee-delete="${f.id}" type="button">删除</button></div></article>`).join('')||'<div class="empty">暂无追加费用或回收记录</div>';}
function posFeeOptions(){const p=posLive().find(p=>p.id===posFeeOwner),kind=$('posFeeKind').value,type=kind==='recovery'?'income':'expense';if(!p)return;const used=new Set([p.entryId,...(p.fees||[]).filter(f=>f.id!==posFeeEditing).map(f=>f.entryId)]);const list=liveEntries().filter(e=>e.type===type&&!used.has(String(e.id))).sort((a,b)=>b.date.localeCompare(a.date));$('posFeeEntry').innerHTML='<option value="">不关联</option>'+list.slice(0,300).map(e=>`<option value="${escapeHtml(e.id)}">${escapeHtml(e.date+' '+(e.note||e.category||'收入'))} · ${money(e.amount)}</option>`).join('');}
function editPosFee(id){const p=posLive().find(p=>p.id===posFeeOwner),f=p?.fees?.find(f=>f.id===id);if(!p)return;posFeeEditing=id||null;$('posFeeForm').reset();$('posFeeKind').value=f?.kind||'expense';$('posFeeName').value=f?.name||'';$('posFeeAmount').value=f?(f.cents/100).toFixed(2):'';$('posFeeDate').value=f?.date||lifeToday();$('posFeeDate').min=p.purchaseDate;$('posFeeDate').max=lifeToday();posFeeOptions();if(f?.entryId&&!$('posFeeEntry').querySelector(`option[value="${CSS.escape(f.entryId)}"]`)){$('posFeeEntry').insertAdjacentHTML('beforeend',`<option value="${escapeHtml(f.entryId)}">原关联账目（保留记录）</option>`);}$('posFeeEntry').value=f?.entryId||'';$('posFeeForm').hidden=false;}
async function savePosFee(e){e.preventDefault();await lifeAction(async()=>{const p=posLive().find(p=>p.id===posFeeOwner);if(!p)throw new Error('物品已删除');if(!posFeeEditing&&(p.fees||[]).length>=500)throw new Error('最多 500 条成本记录');const fee={id:posFeeEditing||lifeId(),name:$('posFeeName').value.trim(),kind:$('posFeeKind').value,cents:JianjiLife.cents($('posFeeAmount').value),date:$('posFeeDate').value,entryId:$('posFeeEntry').value};if(fee.date>lifeToday())throw new Error('只能记录已发生的费用或回收金额');const fees=(p.fees||[]).filter(f=>f.id!==fee.id).concat(fee);JianjiPossessions.validate({...p,fees});await changeLife(()=>p.fees=fees);$('posFeeForm').hidden=true;renderPosFees();showPossession(p.id);toast('成本记录已保存');});}
async function showPosReceipt(){const p=posLive().find(p=>p.id===posDetailId);if(!p?.receiptPhotoId)return;const blob=await photoStore('get',p.receiptPhotoId);if(!blob)throw new Error('凭证图片无法读取');if(!$('appLockOverlay').hidden)return;if(posZoomUrl)URL.revokeObjectURL(posZoomUrl);posZoomUrl=URL.createObjectURL(blob);$('fullRecordPhoto').src=posZoomUrl;$('fullRecordPhoto').alt='购买或保修凭证';open('photoViewerModal');}
async function handlePosExtras(e){const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-pos-costs'))openPosFees(posDetailId);else if(b.hasAttribute('data-pos-enable-reminders'))await posEnableReminders();else if(b.hasAttribute('data-pos-receipt'))await showPosReceipt();else if(b.hasAttribute('data-pos-share'))openPosShare(posDetailId);else if(b.hasAttribute('data-pos-achievement'))openPosShare(posDetailId,'achievement');}
function setupPossessionPlus(){
 $('posOpenTrash').onclick=()=>lifeAction(async()=>{await purgeExpiredPossessions();renderPosTrash();open('posTrashModal');});$('posOpenReview').onclick=()=>openPosShare();
 $('posUndo').onclick=()=>lifeAction(async()=>{const id=posUndoId;clearTimeout(posUndoTimer);$('posUndoBar').hidden=true;posUndoId=null;if(id)await restorePossession(id);});
 $('posTrashList').onclick=e=>lifeAction(async()=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.posRestore)return restorePossession(b.dataset.posRestore);const p=data.possessions.find(p=>p.id===b.dataset.posPurge&&p.deletedAt);if(!p||!confirm('永久删除这件物品、成本记录及照片？回收站无法恢复，原账目不受影响。'))return;await changeLife(()=>data.possessions=data.possessions.filter(x=>x.id!==p.id));for(const id of [p.photoId,p.receiptPhotoId])await cleanPosPhoto(id);renderPossessions();renderPosTrash();});
 $('posReceiptGallery').onclick=()=>{$('posReceiptInput').value='';$('posReceiptInput').click();};$('posReceiptCamera').onclick=()=>{$('posReceiptCameraInput').value='';$('posReceiptCameraInput').click();};for(const id of ['posReceiptInput','posReceiptCameraInput'])$(id).onchange=e=>choosePosReceipt(e.target.files[0]);$('posReceiptRemove').onclick=()=>{++posReceiptGeneration;posReceiptWorking=false;posReceiptId=null;posReceiptBlob=null;++posReceiptRevision;receiptPreview();};
 $('posFeeNew').onclick=()=>editPosFee();$('posFeeCancel').onclick=()=>$('posFeeForm').hidden=true;$('posFeeKind').onchange=posFeeOptions;$('posFeeForm').onsubmit=savePosFee;$('posFeeEntry').onchange=()=>{const e=liveEntries().find(e=>String(e.id)===$('posFeeEntry').value);if(e){$('posFeeAmount').value=e.amount;$('posFeeDate').value=e.date;if(!$('posFeeName').value)$('posFeeName').value=e.note||e.category||'卖出回收';}};
 $('posFeesList').onclick=e=>lifeAction(async()=>{const b=e.target.closest('button'),p=posLive().find(p=>p.id===posFeeOwner);if(!b||!p)return;if(b.dataset.posFeeEdit)return editPosFee(b.dataset.posFeeEdit);if(b.dataset.posFeeDelete&&confirm('删除这条物品成本记录？原账目不会删除。')){await changeLife(()=>p.fees=p.fees.filter(f=>f.id!==b.dataset.posFeeDelete));renderPosFees();showPossession(p.id);}});
 document.addEventListener('visibilitychange',()=>{if(!document.hidden&&ledgerLoaded&&!$('appLockOverlay').hidden){purgeExpiredPossessions().catch(e=>toast(e.message||'回收站清理失败'));syncPosReminders().catch(()=>{});}});
 new MutationObserver(()=>{if(!$('photoViewerModal').classList.contains('show')&&posZoomUrl){URL.revokeObjectURL(posZoomUrl);posZoomUrl=null;}}).observe($('photoViewerModal'),{attributes:true,attributeFilter:['class']});setupPosShare();
 new MutationObserver(()=>{if(!$('posTrashModal').classList.contains('show')&&$('possessionsModal').classList.contains('show')&&posView==='list')renderPossessions();}).observe($('posTrashModal'),{attributes:true,attributeFilter:['class']});
}
